import { create, StateCreator } from 'zustand';

export type CountSlice = { count: number; inc: () => void };
export type UserSlice = { user: string | null; setUser: (u: string | null) => void };
export type Store = CountSlice & UserSlice;

export const createCountSlice: StateCreator<Store, [], [], CountSlice> = (set) => ({
  count: 0,
  inc: () => set((s) => ({ count: s.count + 1 })),
});

export const createUserSlice: StateCreator<Store, [], [], UserSlice> = (set) => ({
  user: null,
  setUser: (u) => set({ user: u }),
});

export const useStore = create<Store>()((...args) => ({
  ...createCountSlice(...args),
  ...createUserSlice(...args),
}));
